import {
    Table,
    GenericColumn,
    StringColumn,
    ReferenceColumn,
    TableNameColumn,
    BooleanColumn,
} from '@servicenow/sdk/core'

export const sys_ui_formatter = Table({
    allowWebServiceAccess: true,
    attributes: {
        'all_tables.text_index_translations': true,
        update_synch: true,
    },
    display: 'name',
    extends: 'sys_metadata',
    label: 'UI Formatter',
    name: 'sys_ui_formatter',
    schema: {
        sys_id: GenericColumn({
            columnType: 'GUID',
            label: 'Sys ID',
            maxLength: 32,
            primary: true,
        }),
        angular_module: StringColumn({
            label: [
                {
                    hint: 'Application used in this formatter',
                    label: 'Angular Module',
                    plural: 'Angular Modules',
                    language: 'en',
                },
            ],
        }),
        formatter: StringColumn({
            attributes: {
                no_truncate: true,
            },
            label: 'Formatter',
            maxLength: 100,
        }),
        seismic_component: ReferenceColumn({
            cascadeRule: 'delete',
            label: 'Seismic Component',
            referenceTable: 'sys_ux_macroponent',
        }),
        name: StringColumn({
            label: 'Name',
        }),
        type: StringColumn({
            default: 'formatter',
            mandatory: true,
            choices: {
                formatter: {
                    label: 'Formatter',
                    sequence: 1,
                },
                component: {
                    label: 'Component',
                    sequence: 2,
                },
            },
            dropdown: 'dropdown_without_none',
            label: 'Type',
        }),
        table: TableNameColumn({
            attributes: {
                allow_public: true,
            },
            label: 'Table',
        }),
        active: BooleanColumn({
            default: true,
            label: 'Active',
        }),
    },
    textIndex: true,
})
